F=".first-principles/analysis-20261010T030229Z.md"; R="${F%/*}/report-${F##*/analysis-}"; { printf '# '; cat <<'FP_EOF'
Should You Take the SF Job Offer
FP_EOF
printf '\n*First-principles analysis · %s*\n\n' "$(date -u '+%-d %B %Y')"
printf '*Read with: [How to read this analysis]''(HOW-TO-READ.md) · [Working file]''(%s) · [All files]''(INDEX.md)*\n\n' "${F##*/}"; awk '
/^```/ { f = !f }
!f && /^## Appendix — process output$/ { exit }
!f && /^\*\*Disclosed:\*\*/ { skip = 1 }
skip && /^#/ { skip = 0 }
skip { if ($0 == "") skip = 0; next }
!f && /^\*\*Pre-check:\*\*/ { next }
!f && /^## Answer$/ { $0 = "## Executive Summary" }
!f && (/^#/ || /^\*\*/) && prev != "" { print "" }
{ print; prev = $0 }' "$F" | cat -s; } > "$R" && echo "$R"

R=".first-principles/report-20261010T030229Z.md"; B="${R##*/}"; B="${B%.md}"
TL=""; [ -s "${R%.md}-fig-trace.svg" ] && TL="![Evidence trace: ground truths, chains and the conclusion]""($B-fig-trace.svg)"
VL=""; [ -s "${R%.md}-fig-verdicts.svg" ] && VL="![Assumption verdict matrix: assumption types against verdicts]""($B-fig-verdicts.svg)"
awk -v t="$TL" -v v="$VL" '
  /^```/ { f = !f }
  !f && /^!\[.*-fig-(trace|verdicts)\.svg\)$/ { next }
  { print }
  !f && $0 == "## 2. Assumptions Table" && v != "" { print ""; print v; print "" }
  !f && $0 == "## 4. Derivation Chains" && t != "" { print ""; print t; print "" }
' "$R" | cat -s > "$R.tmp" && mv "$R.tmp" "$R"
rm -f "$R.tmp"
grep -n "fig-trace\|fig-verdicts" "$R"
